Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] arguments = parameterizedType.getActualTypeArguments();
    Class<?>[] resolvedArguments = new Class[arguments.length];

    for (int i = 0; i < arguments.length; i++) {
        if (arguments[i] instanceof TypeVariable) {
            TypeVariable<?> typeVariable = (TypeVariable<?>) arguments[i];
            resolvedArguments[i] = resolveTypeVariable(targetType, typeVariable);
            if (resolvedArguments[i] == null) {
                return null; // Cannot resolve the type variable
            }
        } else if (arguments[i] instanceof Class) {
            resolvedArguments[i] = (Class<?>) arguments[i];
        } else {
            return null; // Unsupported type
        }
    }

    return resolvedArguments;
}

private static Class<?> resolveTypeVariable(Class<?> targetType, TypeVariable<?> typeVariable) {
    if (targetType.getTypeParameters().length == 0) {
        return null;
    }

    TypeVariable<?>[] typeParameters = targetType.getTypeParameters();
    for (int i = 0; i < typeParameters.length; i++) {
        if (typeParameters[i].equals(typeVariable)) {
            Type genericSuperclass = targetType.getGenericSuperclass();
            if (genericSuperclass instanceof ParameterizedType) {
                ParameterizedType parameterizedType = (ParameterizedType) genericSuperclass;
                Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
                if (actualTypeArguments.length > i && actualTypeArguments[i] instanceof Class) {
                    return (Class<?>) actualTypeArguments[i];
                }
            }
        }
    }

    Class<?> superclass = targetType.getSuperclass();
    if (superclass != null) {
        return resolveTypeVariable(superclass, typeVariable);
    }

    return null;
}

