private void pop(final String descriptor){
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    try {
        if (descriptor.charAt(0) == '(') { // Check if it's a method descriptor
            int current = 1; // Start after the '('
            while (descriptor.charAt(current) != ')') {
                current = popType(descriptor, current);
            }
        } else {
            popType(descriptor, 0);
        }
    } catch (StringIndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Invalid descriptor format", e);
    }
}

private int popType(final String descriptor, int index) {
    char c = descriptor.charAt(index);
    switch (c) {
        case 'B': case 'C': case 'D': case 'F': case 'I': case 'J': case 'S': case 'Z':
            // These are all single-word types
            index++;
            break;
        case 'L':
            // Object type, skip until ';'
            while (descriptor.charAt(index) != ';') {
                index++;
            }
            index++; // Move past the ';'
            break;
        case '[':
            // Array, skip all '[' and then find the component type
            while (descriptor.charAt(index) == '[') {
                index++;
            }
            index = popType(descriptor, index);
            break;
        default:
            throw new IllegalArgumentException("Invalid descriptor character: " + c);
    }
    // Simulate popping from the stack (in a real implementation, you would actually modify the stack)
    // Here we just return the updated index
    return index;
}

