boolean isPrime(int number) {
    if (number <= 1) {
        return false;
    }
    if (number <= 3) {
        return true;
    }
    if (number % 2 == 0 || number % 3 == 0) {
        return false;
    }
    for (int i = 5; i * i <= number; i += 6) {
        if (number % i == 0 || number % (i + 2) == 0) {
            return false;
        }
    }
    return true;
}

int findClosestPrimeWithin11Percent(int desiredCapacity) {
    int upperBound = (int) (desiredCapacity * 1.11);
    for (int i = desiredCapacity; i <= upperBound; i++) {
        if (isPrime(i)) {
            return i;
        }
    }
    return upperBound; // Fallback, though logically there should always be a prime within 11%
}

