Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null) {
        throw new IllegalArgumentException("Bounds list cannot be null");
    }
    long totalSum = 0;
    for (int num : bounds) {
        totalSum += num;
    }
    List<Integer> suffixSum = new ArrayList<>();
    long currentSuffixSum = totalSum;
    for (int num : bounds) {
        suffixSum.add((int) currentSuffixSum);
        currentSuffixSum -= num;
    }
    return new Pair<>(suffixSum, totalSum);
}

