private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null || vertices.size() < 2) {
        return false; // A clique requires at least 2 vertices
    }

    try {
        for (V vertex : vertices) {
            if (!graph.containsVertex(vertex)) {
                return false; // If any vertex is not in the graph, it's not a valid subgraph
            }
        }

        for (V v1 : vertices) {
            for (V v2 : vertices) {
                if (!v1.equals(v2) && !graph.containsEdge(v1, v2)) {
                    return false; // If any two distinct vertices are not connected, it's not a clique
                }
            }
        }

        return true; // All vertices are connected to each other
    } catch (Exception e) {
        return false; // In case of any unexpected error, return false
    }
}

