private void pop(final String descriptor) {
    try {
        char[] chars = descriptor.toCharArray();
        int index = chars[0] == '(' ? 1 : 0; // Check if it's a method descriptor

        while (index < chars.length && chars[index] != ')') {
            switch (chars[index]) {
                case 'B':
                case 'C':
                case 'I':
                case 'S':
                case 'Z':
                case 'F': // Single-slot types
                    index += 1;
                    break;
                case 'D':
                case 'J': // Double-slot types
                    index += 1;
                    break;
                case 'L': // Object Types
                    index = descriptor.indexOf(';', index) + 1;
                    break;
                case '[': // Array Types - treat as a single slot
                    index += 1;
                    break;
                default:
                    throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
            }
        }
    } catch (StringIndexOutOfBoundsException | IllegalArgumentException e) {
        // Handle malformed descriptors with exception handling
        System.err.println("Error popping types from stack: " + e.getMessage());
    }
}

