public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Both path and relativePath must be non-null");
    }

    try {
        // Normalize the input paths
        path = path.replaceAll("\\\\", "/");
        relativePath = relativePath.replaceAll("\\\\", "/");

        // Split the paths into components
        String[] pathComponents = path.split("/");
        String[] relativePathComponents = relativePath.split("/");

        // Use a list to build the final path
        List<String> resultPathComponents = new ArrayList<>(Arrays.asList(pathComponents));

        // Process each component of the relative path
        for (String component : relativePathComponents) {
            if (component.equals("..")) {
                // Go up one directory if possible
                if (resultPathComponents.size() > 1) {
                    resultPathComponents.remove(resultPathComponents.size() - 1);
                }
            } else if (!component.equals(".")) {
                // Add the component if it's not the current directory indicator
                resultPathComponents.add(component);
            }
        }

        // Join the components back into a single path
        return String.join("/", resultPathComponents);
    } catch (Exception e) {
        throw new RuntimeException("Failed to apply relative path", e);
    }
}

